package app.adc.smsanalyzer;
import android.app.*;import android.content.*;import android.os.Bundle;import org.json.*;
public class ArchiveChecks extends Instrumentation {
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 private void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
 @Override public void onStart(){Bundle result=new Bundle();try{Context context=getTargetContext();String name="checks-archive-"+System.currentTimeMillis()+".db";SmsArchive db=new SmsArchive(context,name);long old=System.currentTimeMillis()-400L*86400000L;JSONArray source=new JSONArray();source.put(new JSONObject().put("id",1).put("sender","TEST-ARCHIVE").put("body","ARCHIVE-PRIVATE-CONTENT-ONE ₹100").put("date",old));source.put(new JSONObject().put("id",2).put("sender","TEST-ARCHIVE").put("body","ARCHIVE-PRIVATE-CONTENT-TWO").put("date",old+1));check(db.merge(source)==2,"First import");check(db.merge(source)==0,"Duplicate import");check(db.readAll().length()==2,"Initial count");check(db.merge(new JSONArray())==0&&db.readAll().length()==2,"Inbox absence must retain archive");JSONArray newer=new JSONArray();newer.put(new JSONObject().put("id",3).put("sender","TEST-NEW").put("body","ARCHIVE-PRIVATE-CONTENT-THREE").put("date",System.currentTimeMillis()));check(db.merge(newer)==1&&db.readAll().length()==3,"Append without removing older records");db.close();db=new SmsArchive(context,name);JSONArray restored=db.readAll();check(restored.length()==3,"Reopen persistence");check(restored.getJSONObject(2).getString("body").contains("PRIVATE-CONTENT-ONE"),"Decryption restores original");String revision=db.revision(),signature=db.analysisSignature(revision,"rules-a","1");String snapshot=new JSONObject().put("raw",restored).put("analysed",new JSONArray().put(new JSONObject().put("amount",100))).toString();db.saveAnalysis(signature,snapshot);check(db.readAnalysis(signature).getJSONArray("raw").length()==3,"Encrypted analysis snapshot");char[] padding=new char[6*1024*1024];java.util.Arrays.fill(padding,'a');JSONObject large=new JSONObject(snapshot).put("padding",new String(padding));db.saveAnalysis(signature,large.toString());check(db.readAnalysis(signature).getString("padding").length()==padding.length,"Six-megabyte cache exceeds CursorWindow but restores through chunks");check(db.readAnalysis(db.analysisSignature(revision,"rules-b","1"))==null,"Training change invalidates analysis");check(db.readAnalysis(db.analysisSignature(revision,"rules-a","2"))==null,"App version invalidates analysis");db.close();db=new SmsArchive(context,name);check(db.readAnalysis(signature)!=null,"Cache survives process reopen");JSONArray extra=new JSONArray().put(new JSONObject().put("id",4).put("sender","TEST").put("body","NEW").put("date",old+2));db.merge(extra);check(!db.revision().equals(revision),"New SMS changes archive signature");check(db.readAnalysis(db.analysisSignature(db.revision(),"rules-a","1"))==null,"New SMS invalidates analysis");db.getWritableDatabase().execSQL("UPDATE analysis_cache SET payload=X'00'");check(db.readAnalysis(signature)==null&&db.readAll().length()==4,"Bad cache falls back without losing originals");db.getWritableDatabase().execSQL("DROP TABLE analysis_cache");db.getWritableDatabase().setVersion(1);db.close();db=new SmsArchive(context,name);check(db.readAll().length()==4&&db.readAnalysis(signature)==null,"Version-one migration preserves archive");db.close();byte[] bytes=java.nio.file.Files.readAllBytes(context.getDatabasePath(name).toPath());String raw=new String(bytes,"ISO-8859-1");check(!raw.contains("PRIVATE-CONTENT")&&!raw.contains("TEST-ARCHIVE"),"No plaintext sender or body in SQLite");result.putString("result","PASS: encrypted SQLite import, duplicate refresh, 400-day retention, empty/partial inbox retention, restart/decryption, no plaintext in DB and encrypted analysis cache validation/migration");finish(Activity.RESULT_OK,result);}catch(Throwable e){result.putString("failure",e.toString());finish(Activity.RESULT_CANCELED,result);}}
}
